impl Solution {
    pub fn minimum_deletions(nums: Vec<i32>) -> i32 {
        if nums.len() == 1 {
            return 1;
        }

        let mut min_idx = 0;
        let mut max_idx = 0;

        for i in 1..nums.len() {
            if nums[i] < nums[min_idx] {
                min_idx = i;
            }
            if nums[i] > nums[max_idx] {
                max_idx = i;
            }
        }

        if min_idx == max_idx {
            return 1;
        }

        let left = if min_idx < max_idx {
            max_idx - min_idx + 1
        } else {
            min_idx - max_idx + 1
        };

        let right = if min_idx < max_idx {
            nums.len() - max_idx - min_idx
        } else {
            nums.len() - min_idx - max_idx
        };

        let both = nums.len() - (min_idx + 1) - (max_idx - 1);

        left.min(right).min(both)
    }
}

